import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Familiarity and Active Memory","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/magic/memory-and-familiarity.md","filePath":"game-design/magic/memory-and-familiarity.md"}'),n={name:"game-design/magic/memory-and-familiarity.md"};function o(s,e,l,d,c,m){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="familiarity-and-active-memory" tabindex="-1">Familiarity and Active Memory <a class="header-anchor" href="#familiarity-and-active-memory" aria-label="Permalink to &quot;Familiarity and Active Memory&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; listed decisions remain Unresolved. Existing Accepted foundations retain their scope. <strong>Implementation:</strong> no Batch 04 gameplay implementation established. <strong>Availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation reconciliation only, not runtime validation. <strong>Reviewed:</strong> 2026-10-09 against Batch 04 and <a href="/Syrolands-Public/game-design/magic.html">earlier magic design</a>.</p><p><a href="/Syrolands-Public/guide/magic/memory-and-familiarity.html">Player guide</a> · <a href="/Syrolands-Public/game-design/magic.html">Magic overview</a> · <a href="/Syrolands-Public/game-design/magic/status-and-open-questions.html">Status and open questions</a></p><h2 id="per-pattern-familiarity" tabindex="-1">Per-pattern Familiarity <a class="header-anchor" href="#per-pattern-familiarity" aria-label="Permalink to &quot;Per-pattern Familiarity&quot;">​</a></h2><p>Each Core Pattern has knowledge/practice progression distinct from general Magery and wider discipline/affinity Mastery. <strong>Familiarity is not another skill consuming the skillcap.</strong> Equal Magery can coexist with very different command of individual spells.</p><p>Recently learned, familiar, highly familiar and deeply internalized are illustrative descriptions, not finalized tiers or numeric thresholds. Familiarity may influence reference/recall delay, execution stability, complex modifier use, Concentration burden, recovery from interruption and qualitative feedback. Exact gains, anti-macro rules, scale and decay are unresolved.</p><h2 id="limited-active-memory" tabindex="-1">Limited Active Memory <a class="header-anchor" href="#limited-active-memory" aria-label="Permalink to &quot;Limited Active Memory&quot;">​</a></h2><p>Permanent knowledge is broader than a prepared spell loadout. Active Memory contains a limited set of patterns for immediate access to the <strong>normal casting sequence</strong>, not instant success or zero cast time.</p><table tabindex="0"><thead><tr><th>Access</th><th>Proposed reference cost</th></tr></thead><tbody><tr><td>Memorized</td><td>No extra reference/precast lookup; ordinary casting costs and risks remain</td></tr><tr><td>Highly familiar, not memorized</td><td>Small additional reference/recall delay</td></tr><tr><td>Familiar, not memorized</td><td>Moderate additional delay</td></tr><tr><td>Recently learned or difficult</td><td>Larger additional delay and exposure</td></tr></tbody></table><p>These are relative directions, not timings. No fractional-second or 2–4-second examples become balance here. Consulting/reconstructing a known non-memorized pattern exposes the mage to pressure and interruption; tactical cost should not make all magic sluggish.</p><h2 id="int-and-preparation" tabindex="-1">INT and preparation <a class="header-anchor" href="#int-and-preparation" aria-label="Permalink to &quot;INT and preparation&quot;">​</a></h2><p>INT is proposed as cognitive workspace: Active Memory capacity, the complexity of simultaneously retained patterns and workspace for advanced variants. Simple patterns might cost less than highly modified advanced ones. Exact counts, slots, capacity formulas and complexity costs are unresolved; <a href="/Syrolands-Public/game-design/characters/stats.html#int-broader-mental-capability">Stats</a> retains the undecided INT–mana relationship.</p><p><a href="/Syrolands-Public/game-design/magic.html#meditation-and-concentration">Meditation</a> can support organization, rearrangement, trance preparation, resource recovery and readiness. Higher Meditation may make changes faster/safer; no memorization duration, combat-swap permission or recovery formula is selected. <a href="/Syrolands-Public/game-design/magic/variants-and-glyphs.html#variants-in-active-memory">Variant memory</a> remains a separate unresolved rule.</p><h2 id="physical-reference-under-pressure" tabindex="-1">Physical reference under pressure <a class="header-anchor" href="#physical-reference-under-pressure" aria-label="Permalink to &quot;Physical reference under pressure&quot;">​</a></h2><p><strong>Proposed UX example:</strong> a pursued mage knows Remove Curse but has not memorized it. They open a spellbook, navigate pages, select/read the pattern and attempt the cast while pressure continues. Visible book reading, divided player attention and real interruption opportunities make preparation matter. Bindings are unspecified. ClassicUO support for this interaction is <strong>not established</strong>.</p><p>Hotkey assistance must be considered alongside physical reference, accessibility and remapping without silently turning every known spell into cost-free hotbar access. Server timing cannot wait for a page-turn animation. Client page browsing is presentation/input; any gameplay reference action, valid resource use, delay, interruption and outcome require authoritative server rules. Disclosure of Familiarity/memory state, movement while reading and reference cancellation need later UX and contract work.</p><p>A prepared <a href="/Syrolands-Public/game-design/magic/spellbooks-scrolls-and-reagents.html#scrolls-provide-temporary-access">scroll</a> may bypass part of reference delay at consumable cost; a crafted grimoire may improve indexing. Neither grants permanent knowledge or a completed cast simply by displaying a UI.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Familiarity scale/gain/automation controls; memory capacity and complexity; INT versus mana; preparation time and safe locations; Meditation contribution; reference timing and cancellation; hotkeys/page navigation; UI disclosure; variant memory; accessibility/remapping and anti-macro implications. The server must eventually own knowledge and prepared state, but no serialization or protocol schema is approved.</p>',19)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
